sys_script_client.script:
function onLoad() {
    var eventId = g_form.getValue('number');  // Get Event ID (e.g., EVT0001011)

    var ga = new GlideAjax('GetEventDetails');  // Script Include name
    ga.addParam('sysparm_name', 'getEventDetails');
    ga.addParam('sysparm_event_id', eventId);

    ga.getXMLAnswer(function(response) {
        var data = JSON.parse(response);

        if (data.error) {
            g_form.addInfoMessage('Error: ' + data.error);
        } else {
            var message = '📅 Event Info:<br>' +
                          'Name: ' + data.name + '<br>' +
                          'Date: ' + data.date + '<br>' +
                          'Location: ' + data.location + '<br>' +
                          'Status: ' + data.status + '<br>' +
                          'Contact: ' + data.contact + '<br>' +
                          'Email: ' + data.email;

            g_form.addInfoMessage(message);
        }
    });
}
